// Symptom: a span with the admin label class inside a button loses its type size.
// The span should inherit the button's 14px font size, not fall back to the default.
await page.goto('/ops/rules');
const button = page.getByRole('button', { name: 'Save rule' });
await expect(button).toBeVisible();
const label = button.locator('span').first();
await expect(label).toHaveCSS('font-size', '14px');
```

```js
// Assumes the admin rules screen has a button whose label span should keep the button's type size.
await page.goto('/ops/rules');
const button = page.getByRole('button').first();
await expect(button).toBeVisible();
const buttonSize = await button.evaluate((el) => getComputedStyle(el).fontSize);
const label = button.locator('span').first();
await expect(label).toHaveCSS('font-size', buttonSize);
```

